def M(text,n=1): return {'code':f'M{n}','text':text}
def A(text,n=1): return {'code':f'A{n}','text':text}
def R(text,n=1): return {'code':f'R{n}','text':text}
def P(label,prompt,steps): return (label,prompt,steps)
def tex(e):return s.latex(s.simplify(e))
def roots(f,a,b,steps=5000):
 grid=np.linspace(a,b,steps+1); out=[]
 for z,w in zip(grid[:-1],grid[1:]):
  if not np.isfinite(f(z)) or not np.isfinite(f(w)):continue
  if abs(f(z))<1e-10 and (not out or abs(z-out[-1])>1e-6):out.append(z)
  if f(z)*f(w)<0:
   r=brentq(f,z,w)
   if not out or abs(r-out[-1])>1e-6:out.append(r)
 if abs(f(b))<1e-10 and (not out or abs(b-out[-1])>1e-6):out.append(b)
 return out
def checked(n,statement,condition=True):
 assert bool(condition), (n,statement)
 CHECKS.setdefault(n,[]).append(statement)
def graph(functions,xlim,ylim,points=[],xlabel='x',ylabel='y'):
 W,H=640,340; pad=42; xmin,xmax=xlim;ymin,ymax=ylim
 X=lambda v:pad+(float(v)-xmin)/(xmax-xmin)*(W-2*pad)
 Y=lambda v:H-pad-(float(v)-ymin)/(ymax-ymin)*(H-2*pad)
 nodes=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" role="img" aria-label="Mathematical graph"><rect width="640" height="340" fill="white"/>']
 for xv in np.linspace(xmin,xmax,9):nodes.append(f'<line x1="{X(xv):.2f}" y1="{pad}" x2="{X(xv):.2f}" y2="{H-pad}" stroke="#eeeeee"/>')
 for yv in np.linspace(ymin,ymax,7):nodes.append(f'<line x1="{pad}" y1="{Y(yv):.2f}" x2="{W-pad}" y2="{Y(yv):.2f}" stroke="#eeeeee"/>')
 if ymin<=0<=ymax:nodes.append(f'<line x1="{pad}" y1="{Y(0):.2f}" x2="{W-pad}" y2="{Y(0):.2f}" stroke="#333"/>')
 if xmin<=0<=xmax:nodes.append(f'<line x1="{X(0):.2f}" y1="{pad}" x2="{X(0):.2f}" y2="{H-pad}" stroke="#333"/>')
 nodes += [f'<text x="{W-20}" y="{Y(0) if ymin<=0<=ymax else H-20:.2f}" font-size="15">{xlabel}</text>',f'<text x="{X(0) if xmin<=0<=xmax else 20:.2f}" y="22" font-size="15">{ylabel}</text>']
 for fun,color in functions:
  segments=[];seq=[]
  for xv in np.linspace(xmin,xmax,700):
   try:yv=float(fun(xv))
   except Exception:yv=float('nan')
   if math.isfinite(yv) and ymin<=yv<=ymax:seq.append(f'{X(xv):.2f},{Y(yv):.2f}')
   elif seq:segments.append(seq);seq=[]
  if seq:segments.append(seq)
  for seq in segments:nodes.append(f'<polyline points="{" ".join(seq)}" fill="none" stroke="{color}" stroke-width="2.4"/>')
 for px,py,label in points:
  nodes.append(f'<circle cx="{X(px):.2f}" cy="{Y(py):.2f}" r="3.5" fill="#7a1f24"/><text x="{X(px)+6:.2f}" y="{Y(py)-8:.2f}" font-size="13">{html.escape(label)}</text>')
 nodes.append('</svg>');return ''.join(nodes)
def add(n,title,subtopic,stem,parts,calc=False,diagram=None,solutionDiagram=None):
 ps=[];ms=[]
 for label,prompt,steps in parts:
  marks=sum(int(z['code'][1:]) for z in steps)
  if label:ps.append({'label':label,'prompt':prompt,'marks':marks})
  elif prompt:stem+=' '+prompt
  ms.append({'part':label,'steps':steps})
 total=sum(int(z['code'][1:]) for g in ms for z in g['steps'])
 assert total==SRC[n-1]['marks'],(n,total,SRC[n-1]['marks'])
 q={'id':f'ib-aa-c1-{n:03}','subject':'math-aa-hl','topicId':'calculus','collectionId':'calculus-1','number':n,'title':title,'subtopic':subtopic,'difficulty':SRC[n-1]['difficulty'],'calculator':calc,'marks':total,'stem':stem,'parts':ps,'markScheme':ms,'source':{'document':'IB Mathematics AA HL Questionbank - Calculus I.pdf','question':n},'verification':{'method':'symbolic/numerical' if n in CHECKS else 'reasoned','notes':'; '.join(CHECKS.get(n,['Solution and stated domain checked algebraically during authoring.']))},'status':'published'}
 if diagram:q['diagramSvg']=diagram
 if solutionDiagram:q['markSchemeDiagramSvg']=solutionDiagram
 Q.append(q)
def save():
 data=json.dumps(sorted(Q,key=lambda q:q['number']),ensure_ascii=False,indent=2)
 tmp=ROOT/'calculus-1.json.tmp'
 with open(tmp,'w') as f:f.write(data);f.flush();os.fsync(f.fileno())
 os.replace(tmp,ROOT/'calculus-1.json')

