add(51,'An open container','Optimization',r'A workshop makes an open cuboid with square base side $x$ metres and height $y$ metres. The volume is $108\text{ m}^3$. Let $A(x)$ be its outside surface area.',[P('a',r'Show that $A(x)=x^2+432/x$.',[M(r'$x^2y=108$.'),A(r'$y=108/x^2$.'),M(r'There is one base and four sides: $A=x^2+4xy$.'),A(r'$A=x^2+432/x$.')]),P('b',r'Find $A\prime(x)$.',[M('Differentiate $x^2+432x^{-1}$.'),A(r'$\boxed{A\prime=2x-432/x^2}$.')]),P('c','Find the base side length that minimizes area.',[M(r'$2x-432/x^2=0$.'),A(r'$x^3=216$.'),A(r'$x=6$ m.'),R(r'$A\prime\prime=2+864/x^3>0$ for $x>0$, confirming a minimum.')]),P('d',r'Each can of sealant covers $7\text{ m}^2$ and costs £18. Find the cost of the cans required for the minimum-area container.',[M(r'Evaluate the minimum area.'),A(r'$A(6)=36+72=108\text{ m}^2$.'),M(r'$108/7=15.428\ldots$ cans.'),A(r'Buy $16$ whole cans.'),A(r'$\boxed{16\times18=£288}$.')])])
