add(53,'Velocity signs and slowing down','Interpreting derivative graphs',r'The graph shows the velocity of a moving weight for $0\le t\le4.5$ seconds. Its labelled zeros are at $C$, $E$ and $G$, where $t=1.5$, $3$ and $4.5$. There is a local maximum at $D$.',[P('a','State the velocity at $C$.',[A(r'$\boxed{0\text{ m s}^{-1}}$.')]),P('b','State when the weight changes direction for $0<t<4.5$.',[A(r'$t=1.5$ s.'),A(r'$t=3$ s; velocity changes sign at both.')]),P('c','State the acceleration at $D$ and justify.',[A(r'$\boxed{0\text{ m s}^{-2}}$.'),R('Acceleration is the gradient of the velocity graph, which is zero at its smooth maximum.')]),P('d','Explain why the weight slows down between $D$ and $E$.',[R('Velocity is positive in this interval.'),R('The velocity graph is decreasing, so acceleration is negative and speed decreases.')])],diagram=dg)
add(54,'Normal to a composition','Product and chain rules',r'Let $h=f\circ g$. Given $g(4)=7$, $g\prime(4)=-3$ and $f\prime(7)=5$, find the gradient of the normal to $h$ at $x=4$.',[P('','',[M(r'Apply the chain rule: $h\prime(x)=f\prime(g(x))g\prime(x)$.'),M(r'Evaluate the composite derivative at $x=4$.'),A(r'$h\prime(4)=f\prime(7)g\prime(4)$, using the inner value $g(4)=7$.'),M(r'Substitute the supplied derivative values: $5(-3)$.'),A(r'The tangent gradient is $-15$.'),M('Use the negative reciprocal of the tangent gradient for the normal.'),A(r'The normal gradient is $-1/(-15)=\boxed{1/15}$.')])])
D=1+2*t*s.exp(-t); N=2*s.exp(-t)*(1-t); checked(55,'Logarithmic displacement derivatives and initial acceleration verified symbolically.',s.diff(s.log(D),t,2).subs(t,0)==-8 and s.simplify(s.diff(s.log(D),t)-N/D)==0)
add(55,'A logarithmic motion model','Kinematics: differentiation',r'A particle has displacement $s(t)=\ln(1+2te^{-t})$ metres, $t\ge0$.',[P('a','Find the velocity.',[M('Use the logarithmic chain rule.'),M(r'$\frac d{dt}(2te^{-t})=2e^{-t}(1-t)$.'),A(r'$\boxed{v(t)=\frac{2e^{-t}(1-t)}{1+2te^{-t}}}$.')]),P('b','Find the acceleration.',[M('Apply the quotient rule.'),A(r'The numerator derivative is $2e^{-t}(t-2)$.'),A(r'$\boxed{a(t)=\frac{2e^{-t}(t-2)(1+2te^{-t})-[2e^{-t}(1-t)]^2}{(1+2te^{-t})^2}}$.')]),P('c','Find the initial acceleration.',[M(r'$a(0)=[-4(1)-4]/1$.'),A(r'$\boxed{-8\text{ m s}^{-2}}$.')])])
sa=lambda z:10*z+8*math.exp(-z/2)-8; sb=lambda z:9.5*z+5*math.exp(-z/3)-5
tcross=brentq(lambda z:sa(z)-sb(z),.1,15);tfinish=brentq(lambda z:sa(z)-300,25,35);remaining=300-sb(tfinish)
checked(56,'Overtaking and finishing times found by bracketing and substitution.',abs(sa(tcross)-sb(tcross))<1e-8 and abs(sa(tfinish)-300)<1e-8)
add(56,'Comparing two runners','Kinematics: differentiation',r'Two runners compete in a 300 m race. Their displacements from the start are $s_A(t)=10t+8e^{-t/2}-8$ and $s_B(t)=9.5t+5e^{-t/3}-5$, in metres, with $t\ge0$ in seconds.',[P('a',r'Find runner A’s velocity and show that it reaches $9\text{ m s}^{-1}$ at $t=2\ln4$.',[M('Differentiate $s_A$.'),A(r'$v_A=10-4e^{-t/2}$.'),M(r'$9=10-4e^{-t/2}\Rightarrow e^{-t/2}=1/4$.'),M('Take logarithms.'),A(r'$t=2\ln4$ seconds.')]),P('b','Find runner A’s acceleration and show that A is always speeding up.',[A(r'$a_A=2e^{-t/2}$.'),R(r'$a_A>0$ for $t\ge0$.'),R(r'$v_A\ge6>0$, so velocity and acceleration have the same sign.')]),P('c','Find when A overtakes B, excluding $t=0$.',[M(r'Solve $0.5t+8e^{-t/2}-5e^{-t/3}-3=0$ for $t>0$.'),A(f'$\\boxed{{t={tcross:#.3g}\\text{{ s}}}}$.')]),P('d','Find B’s distance from the finish when A finishes.',[M(r'Solve $s_A(t)=300$.'),A(f'$t={tfinish:.6f}\\text{{ s}}$.'),M('Evaluate $300-s_B(t)$ at this time.'),A(f'$\\boxed{{{remaining:#.3g}\\text{{ m}}}}$.')])],calc=True)
add(57,'A translated sinusoidal graph','Trigonometric differentiation',r'Let $f(x)=a\sin(kx)+c$ on $0\le x\le20$, with $k>0$. Consecutive minimum and maximum points are $P(5,8)$ and $Q(15,20)$; these are the only extrema in this interval.',[P('a','Find $c$, $k$ and $a$.',[M('Use the midpoint of maximum and minimum values.'),A(r'$c=14$.'),M('Half a period is $15-5=10$, so the period is $20$.'),A(r'$k=2\pi/20=\pi/10$.'),M(r'$f(5)=a\sin(\pi/2)+14=8$.'),A(r'$a=-6$.')]),P('b','The graph is translated horizontally so that its minimum is now $(8,8)$. State the translation and find the new function $g$.',[A(r'Translation $\binom30$.'),M(r'Replace $x$ by $x-3$.'),A(r'$\boxed{g(x)=-6\sin(\pi(x-3)/10)+14}$ on $3\le x\le23$.')]),P('c','Find the inflexion where $g$ changes from concave up to concave down, then find its maximum positive rate of change.',[M(r'$g\prime\prime=(3\pi^2/50)\sin(\pi(x-3)/10)$.'),M('The relevant sine sign change is positive to negative at phase $\pi$.'),A(r'$\boxed{x=13}$.'),M(r'$g\prime=-(3\pi/5)\cos(\pi(x-3)/10)$.'),A(r'At $x=13$, $\cos\pi=-1$.'),A(r'Maximum positive rate $\boxed{3\pi/5}$.')])],diagram=graph([(lambda z:-6*math.sin(math.pi*z/10)+14,'#7a1f24')],(0,20),(5,23),[(5,8,'P(5, 8)'),(15,20,'Q(15, 20)')]))
add(58,'First principles and parallel tangents','First principles',r'Let $f(x)=-2x^3+6x+7$.',[P('a',r'Expand $(x+h)^3$.',[M('Use the binomial coefficients $1,3,3,1$.'),A(r'$x^3+3x^2h+3xh^2+h^3$.')]),P('b',r'Use first principles to show that $f\prime(x)=-6x^2+6$.',[M(r'Form $[f(x+h)-f(x)]/h$.'),A(r'The numerator is $-6x^2h-6xh^2-2h^3+6h$.'),M(r'Divide by $h$ and take $h\to0$.'),A(r'$f\prime(x)=-6x^2+6$.')]),P('c','The tangent at $A(3,-29)$ is parallel to the tangent at a distinct point $B$. Find $B$.',[A(r'$f\prime(3)=-48$.'),M(r'$-6x^2+6=-48\Rightarrow x=\pm3$.'),A(r'The distinct point has $x=-3$.'),A(r'$\boxed{B=(-3,43)}$.')]),P('d','Find where $f$ is increasing.',[M(r'$-6x^2+6>0$.'),A(r'$x^2<1$.'),A(r'$\boxed{-1<x<1}$.')]),P('e','State the range of possible gradients.',[R(r'$-6x^2+6\le6$, with equality at $x=0$.'),A(r'$\boxed{(-\infty,6]}$.')])])
