add(59,'Fractional-power motion','Kinematics: differentiation',r'Let $f(x)=\frac23\sqrt{x}(12x^2-10x+3)$ for $x>0$.',[P('a',r'Show that $f\prime(x)=\dfrac{20x^2-10x+1}{\sqrt{x}}$.',[M('Apply the product rule.'),A(r'$f\prime=\frac{12x^2-10x+3}{3\sqrt{x}}+\frac23\sqrt{x}(24x-10)$.'),M(r'Put both terms over $\sqrt{x}$.'),A(r'The numerator simplifies to $20x^2-10x+1$.')]),P('b','Find the stationary-point $x$-coordinates.',[M(r'$20x^2-10x+1=0$.'),A(r'$x=(10\pm\sqrt{100-80})/40$.'),A(r'$\boxed{x=\frac{5\pm\sqrt5}{20}}$.')]),P('c',r'A particle has displacement $s(t)=\frac23\sqrt{t}(12t^2-10t+3)$ for $t\ge0$. Find the total time it moves left.',[M('It moves left where the velocity is negative.'),A(r'For $t>0$, $\sqrt t>0$, so this is between the two roots from (b).'),M('Subtract the earlier root from the later root.'),A(r'$\boxed{\frac{\sqrt5}{10}\text{ s}}$.')])])
