add(63,'Rational curve analysis','Stationary points and concavity',r'Let $f(x)=\dfrac{3x^2-9x+12}{x-2}$, $x\ne2$.',[P('a','State the vertical asymptote.',[A(r'$\boxed{x=2}$.')]),P('b','Find and classify the stationary points.',[M(r'$f\prime=3-6/(x-2)^2$.'),M(r'$f\prime=0\Rightarrow(x-2)^2=2$.'),A(r'$x=2\pm\sqrt2$.'),A(r'Coordinates: $(2-\sqrt2,3-6\sqrt2)$ and $(2+\sqrt2,3+6\sqrt2)$.',2),R(r'$f\prime\prime=12/(x-2)^3$ is negative at the first and positive at the second: maximum, then minimum.')]),P('c','Find the oblique asymptote.',[M('Divide the numerator by $x-2$.'),A(r'$f(x)=3x-3+6/(x-2)$.'),R(r'$6/(x-2)\to0$ as $x\to\pm\infty$.'),A(r'$\boxed{y=3x-3}$.')]),P('d','Sketch the graph, showing asymptotes, intercepts and stationary points.',[A('Two separated branches around $x=2$.'),A('Both approach the oblique asymptote from their appropriate sides.'),A(r'The $y$-intercept is $(0,-6)$.'),A(r'No $x$-intercepts: $x^2-3x+4$ has negative discriminant.'),A('Correctly place and label the maximum and minimum from (b).')]),P('e','State the range.',[A(r'$\boxed{(-\infty,3-6\sqrt2]\cup[3+6\sqrt2,\infty)}$.')])],solutionDiagram=sol63)
add(64,'Depth and wet surface area in a cone','Related rates',r'Water enters an inverted conical funnel at $2\pi\text{ cm}^3\text{ s}^{-1}$. The semi-vertical angle is $45^\circ$. Let the water depth be $h$, its surface radius $r$, and its wetted curved surface area $A$.',[P('a',r'Show $V=\pi h^3/3$.',[M(r'$r=h\tan45^\circ=h$.'),A(r'$V=\frac13\pi r^2h=\frac13\pi h^3$.')]),P('b',r'Find $dh/dt$ when $h=4$ cm.',[M('Differentiate volume with respect to time.'),A(r'$dV/dt=\pi h^2\,dh/dt$.'),A(r'$dV/dt=2\pi$.'),M(r'$2\pi=16\pi\,dh/dt$.'),A(r'$\boxed{dh/dt=1/8\text{ cm s}^{-1}}$.')]),P('c','Find $dA/dt$ at that instant.',[M(r'The slant height is $\ell=\sqrt{r^2+h^2}$.'),A(r'$\ell=\sqrt2h$.'),M(r'$A=\pi r\ell$.'),A(r'$A=\pi\sqrt2h^2$.'),M(r'$dA/dt=2\pi\sqrt2h\,dh/dt$.'),M(r'Substitute $h=4$ and $dh/dt=1/8$.'),A(r'$\boxed{dA/dt=\pi\sqrt2\text{ cm}^2\text{ s}^{-1}}$.')])])
add(65,'A rising rocket','Related rates',r'An observer is 400 m horizontally from a launch pad. A rocket rises vertically at a constant $30\text{ m s}^{-1}$. Let its height be $h$, its angle of elevation from the observer be $\theta$, and its distance from the observer be $s$.',[P('a',r'Express $h$ in terms of $\theta$.',[M(r'$\tan\theta=h/400$.'),A(r'$\boxed{h=400\tan\theta}$.')]),P('b',r'Find $d\theta/dt$ when $h=300$ m.',[M('Differentiate with respect to time.'),A(r'$dh/dt=400\sec^2\theta\,d\theta/dt$.'),A(r'$\tan\theta=300/400=3/4$.'),M(r'$\sec^2\theta=1+\tan^2\theta$.'),A(r'$\sec^2\theta=25/16$.'),M(r'$30=400(25/16)\,d\theta/dt$.'),A(r'$\boxed{d\theta/dt=0.048\text{ rad s}^{-1}}$.')]),P('c','Find $ds/dt$ at the same instant.',[M(r'$s^2=400^2+h^2$.'),M(r'$2s\,ds/dt=2h\,dh/dt$.'),A(r'$s=500$ m.'),A(r'$\boxed{ds/dt=(300/500)30=18\text{ m s}^{-1}}$.')])])
add(66,'Symmetry of parallel tangents','Tangents and normals',r'Let $f(x)=\dfrac{3x+2}{x-4}$, $x\ne4$.',[P('a','Find both asymptotes, their intersection $Q$, and both axis intercepts.',[A(r'Vertical asymptote $x=4$.'),A(r'Horizontal asymptote $y=3$.'),A(r'$Q=(4,3)$.'),A(r'$x$-intercept $(-2/3,0)$.'),A(r'$y$-intercept $(0,-1/2)$.')]),P('b',r'Show $f\prime(x)=-14/(x-4)^2$.',[M(r'The quotient-rule numerator is $3(x-4)-(3x+2)=-14$.'),A(r'$f\prime(x)=-14/(x-4)^2$.')]),P('c','Find the tangent at $P$, where $x=5$.',[A(r'$P=(5,17)$.'),M(r'$f\prime(5)=-14$.'),A(r'$\boxed{y=-14x+87}$.')]),P('d','A distinct point $S$ has a tangent parallel to that at $P$. Find $S$.',[M(r'$-14/(x-4)^2=-14$.'),A(r'$(x-4)^2=1$.'),A(r'The distinct solution is $x=3$.'),A(r'$\boxed{S=(3,-11)}$.')]),P('e','Show $Q$ is the midpoint of $PS$.',[M(r'The midpoint is $((5+3)/2,(17-11)/2)$.'),A(r'This is $(4,3)=Q$.')])])
add(67,'Exact trigonometric extrema','Trigonometric differentiation',r'Let $f(x)=2\sin x-2\cos x$ for $0\le x\le2\pi$. Its $x$-intercepts are $A$ and $C$, in that order, and its maximum is $B$.',[P('a','Find the exact coordinates of $A$ and $C$.',[M(r'$2\sin x-2\cos x=0$.'),M(r'$\tan x=1$; $\cos x=0$ gives no solution of the original equation.'),A(r'The first solution is $x=\pi/4$.'),A(r'The second is $x=5\pi/4$.'),A(r'$A=(\pi/4,0)$.'),A(r'$C=(5\pi/4,0)$.')]),P('b',r'Find $f\prime$.',[M('Differentiate both trigonometric terms.'),A(r'$f\prime=2\cos x+2\sin x$.')]),P('c','Find $B$ exactly.',[M(r'$f\prime=0\Rightarrow\tan x=-1$.'),A(r'$x=3\pi/4,7\pi/4$.'),M(r'$f\prime\prime=-2\sin x+2\cos x$.'),R(r'At $3\pi/4$, $f\prime\prime=-2\sqrt2<0$.'),A(r'$f(3\pi/4)=2\sqrt2$.'),A(r'$\boxed{B=(3\pi/4,2\sqrt2)}$.')])])
