add(70,'Triangle in a semicircle','Optimization',r'A semicircle has centre $(0,0)$ and radius 6. A right triangle has vertices $A=(-6,0)$, $C=(x,0)$ and $B$ on the upper semicircle directly above $C$, where $-6<x<6$.',[P('a','Give the coordinates of $B$ in terms of $x$.',[M(r'$x^2+y^2=36$, with $y>0$.'),A(r'$\boxed{B=(x,\sqrt{36-x^2})}$.')]),P('b','Find the area of triangle $ABC$.',[M('Use half base times height.'),A(r'$\boxed{A(x)=\frac12(x+6)\sqrt{36-x^2}}$.')]),P('c',r'Show that $A\prime(x)=(18-3x-x^2)/\sqrt{36-x^2}$.',[M('Use product and chain rules.'),A(r'$A\prime=\frac12\sqrt{36-x^2}-\frac{x(x+6)}{2\sqrt{36-x^2}}$.'),A(r'Combining the numerator yields $(18-3x-x^2)/\sqrt{36-x^2}$.')]),P('d','Find $B$ when the area is maximal.',[M(r'$18-3x-x^2=0$.'),A(r'$(x+6)(x-3)=0$.'),R(r'$x=-6$ is an endpoint; the interior stationary value is $x=3$.'),R(r'$A\prime>0$ before 3 and $A\prime<0$ after 3.'),A(r'$y=\sqrt{27}=3\sqrt3$.'),A(r'$\boxed{B=(3,3\sqrt3)}$.')])],diagram=svg70)
add(71,'Rectangle and tangent parabola','Optimization',r'Let $f(x)=25-x^2$. A rectangle has bottom vertices $(-a,0)$ and $(a,0)$ and top vertices on the graph of $f$, where $0<a<5$.',[P('a','Find the $x$-intercepts of $f$.',[M(r'$25-x^2=0$.'),A(r'$\boxed{(-5,0),(5,0)}$.')]),P('b',r'Show that the rectangle area is $50a-2a^3$.',[M(r'Width $=2a$ and height $=25-a^2$.'),A(r'$A=2a(25-a^2)=50a-2a^3$.')]),P('c','Find the value of $a$ that maximizes the area.',[M(r'$A\prime=50-6a^2=0$.'),A(r'$a^2=25/3$.'),A(r'$\boxed{a=5/\sqrt3}$.'),R(r'$A\prime\prime=-12a<0$, confirming a maximum.')]),P('d',r'Let $g(x)=(x-5)^2+k$. Show that intersections satisfy $2x^2-10x+k=0$.',[M(r'$25-x^2=x^2-10x+25+k$.'),A(r'Rearrangement gives $2x^2-10x+k=0$.')]),P('e','Find $k$ if the two graphs meet exactly once.',[M('A single intersection requires zero discriminant.'),A(r'$(-10)^2-4(2)k=0$.'),M(r'$8k=100$.'),A(r'$k=25/2$.'),R(r'The quadratic then has a repeated real root $x=5/2$, so $\boxed{k=25/2}$.')])])
