add(72,'Velocity and greatest speed','Kinematics: differentiation',r'A particle has velocity $v(t)=\dfrac{(t^2-1.44)\sin t}{3}$ metres per second for $0\le t\le2.5$.',[P('a','Find when the particle first changes direction.',[M(r'For $0<t<2.5$, $\sin t>0$; the sign changes at $t^2=1.44$.'),A(r'$\boxed{t=1.20\text{ s}}$.')]),P('b',r'Find all times when acceleration is $1\text{ m s}^{-2}$.',[M(r'$a(t)=[2t\sin t+(t^2-1.44)\cos t]/3$.'),M('Solve $a(t)=1$ on the given interval.'),A('$\\boxed{t='+',\ '.join(f'{z:#.3g}' for z in ar72)+'\\text{ s}}$.')]),P('c','Find the acceleration when the speed is greatest.',[M('Compare $|v|$ at the endpoints and the solutions of $a=0$.'),A(f'The maximum speed occurs at $t={best72:.6f}$ s, giving $\\boxed{{a={0 if abs(a72(best72))<1e-10 else a72(best72):#.3g}\\text{{ m s}}^{{-2}}}}$.')])],calc=True)
c73=brentq(lambda z:12800*z*math.exp(4*z)+100,-3,-1);time73=8+math.log(.01)/c73
checked(73,'Supplement rate parameter solves the supplied derivative observation.',abs(12800*c73*math.exp(4*c73)+100)<1e-8)
add(73,'Population growth followed by decline','Exponential models and rates',r'A culture starts with 800 bacteria. Before a supplement is added, its population is $P_A(t)=a\,2^{kt}$, where $t$ is measured in minutes. The population quadruples in the first 4 minutes. At $t=8$, a supplement is added and the model becomes $P_B(t)=be^{c(t-8)}$, with $t>8$.',[P('a','Find $a$ and show $k=1/2$.',[A(r'$a=800$.'),M(r'$2^{4k}=4=2^2$.'),A(r'$k=1/2$.')]),P('b','Find the population at $t=8$.',[A(r'$\boxed{800\cdot2^4=12800}$.')]),P('c','Using the original growth model, find $P_A\prime(12)$ exactly.',[M(r'$P_A\prime(t)=400\ln2\cdot2^{t/2}$.'),A(r'$\boxed{P_A\prime(12)=25600\ln2}$ bacteria per minute.')]),P('d','State $b$.',[A(r'$\boxed{12800}$.')]),P('e',r'At $t=12$, population is decreasing by 100 bacteria per minute. Given $c<-1$, find $c$ to three significant figures.',[M(r'$P_B\prime(t)=12800ce^{c(t-8)}$.'),A(r'$12800ce^{4c}=-100$.'),M('Solve numerically on $c<-1$.'),A(f'$\\boxed{{c={c73:#.3g}}}$.')]),P('f','Find when the population first drops below 1% of its maximum.',[M(r'$12800e^{c(t-8)}<128$.'),M(r'$t>8+\ln(0.01)/c$, since $c<0$.'),A(f'The threshold is $\\boxed{{t={time73:#.3g}\\text{{ min}}}}$; it is below 1% immediately after this time.')])],calc=True)
add(74,'Matching a piecewise derivative','Continuity and differentiability',r'Let $f(t)=\begin{cases}at^2+bt,&t\le3,\\|t-3|+4,&t>3.\end{cases}$ Both $f$ and its derivative are continuous at $t=3$. Find $a$ and $b$.',[P('','',[M('Match the left and right function values at 3.'),A(r'$9a+3b=4$.'),M(r'For $t>3$, $f(t)=t+1$, with derivative 1.'),A(r'$6a+b=1$.'),M('Solve the two simultaneous equations.'),A(r'$\boxed{a=-1/9,\quad b=5/3}$.')])])
add(75,'Implicit logarithm and tangent','Implicit differentiation',r'The curve $x^2y+\ln(xy)=2$ has $x>0$, $y>0$.',[P('a',r'Find $dy/dx$ in terms of $x,y$.',[M(r'Differentiate: $2xy+x^2y\prime+(y+xy\prime)/(xy)=0$.'),A(r'$2xy+x^2y\prime+1/x+y\prime/y=0$.'),M(r'Collect $y\prime$ terms.'),A(r'$\boxed{y\prime=-\frac{2xy+1/x}{x^2+1/y}}$.')]),P('b',r'Find the tangent at $P(2,1/2)$.',[M(r'Substitute $x=2$, $y=1/2$ into the derivative.'),A(r'$y\prime=-5/12$.'),A(r'$\boxed{y-\frac12=-\frac5{12}(x-2)}$.')])])
add(76,'A product tangent from local information','Product and chain rules',r'Let $f(x)=\sqrt{3x+4}$ for $x\ge-4/3$. The tangent to a second function $g$ at $x=7$ is $y=2x-3$.',[P('a',r'Find $f(7)$ and $f\prime(7)$.',[M(r'$f(7)=\sqrt{25}$.'),A(r'$f(7)=5$.'),M(r'$f\prime(x)=3/(2\sqrt{3x+4})$.'),A(r'$f\prime(7)=3/10$.')]),P('b',r'Find $g\prime(7)$.',[M('Use the gradient of the given tangent.'),A(r'$\boxed{2}$.')]),P('c',r'Find $g(7)$.',[M(r'Substitute $x=7$ into the tangent equation.'),A(r'$\boxed{11}$.')]),P('d',r'Let $h=fg$. Find its tangent at $x=7$.',[M(r'$h\prime=f\prime g+fg\prime$.'),A(r'$h\prime(7)=(3/10)(11)+5(2)$.'),A(r'$h\prime(7)=133/10$.'),M(r'$h(7)=f(7)g(7)$.'),A(r'$h(7)=55$.'),M('Use point-gradient form.'),A(r'$\boxed{y-55=\frac{133}{10}(x-7)}$.')])])
dg77=graph([(lambda z:8*math.sin(math.pi*(z-1)/8)+4,'#7a1f24')],(1,17),(-6,14),[(5,12,'P(5, 12)'),(13,-4,'Q(13, -4)')])
add(77,'Sinusoidal parameters and gradient','Trigonometric differentiation',r'The graph of $f(x)=a\sin(k(x-d))+c$ on $1\le x\le17$ is shown, with $a,k>0$. Consecutive extrema are maximum $P(5,12)$ and minimum $Q(13,-4)$.',[P('a','Find $a$ and $c$.',[M('Use half the difference and the mean of the extreme values.'),A(r'$a=8$.'),A(r'$c=4$.')]),P('b','Find $k$ and the smallest positive $d$.',[M('Half a period is 8, so the period is 16.'),A(r'$k=\pi/8$.'),M(r'At the maximum, $k(5-d)=\pi/2$ modulo $2\pi$.'),A(r'$d=1$ is the smallest positive value.')]),P('c',r'Find $f\prime(x)$.',[M('Apply the chain rule.'),A(r'$f\prime=8(\pi/8)\cos(\pi(x-1)/8)$.'),A(r'$\boxed{f\prime=\pi\cos(\pi(x-1)/8)}$.')]),P('d',r'Find all $x$ in the stated domain where the gradient is $-\pi$.',[M(r'$\pi\cos(\pi(x-1)/8)=-\pi$.'),A(r'$\cos(\pi(x-1)/8)=-1$.'),M('The phase lies in $[0,2\pi]$.'),A(r'The only phase solution is $\pi$.'),M(r'$\pi(x-1)/8=\pi$.'),A(r'$\boxed{x=9}$.')])],diagram=dg77)
add(78,'Minimum curved area of a cone','Optimization',r'An open cone has volume $32\pi/3\text{ cm}^3$, base radius $r$ and height $h$. Only its curved surface is present. Let its area be $A$.',[P('a',r'Show $A=\pi\sqrt{r^4+1024/r^2}$.',[M(r'$\pi r^2h/3=32\pi/3\Rightarrow h=32/r^2$.'),M(r'$A=\pi r\sqrt{r^2+h^2}$.'),A(r'$A=\pi\sqrt{r^4+1024/r^2}$.')]),P('b',r'The minimum occurs at $r=2^k$. Find $k$.',[M('Minimizing $A$ is equivalent to minimizing $F=r^4+1024/r^2$, for $r>0$.'),A(r'$F\prime=4r^3-2048/r^3$.'),M(r'$F\prime=0\Rightarrow r^6=512=2^9$.'),A(r'$r=2^{3/2}$.'),R(r'$F\prime\prime=12r^2+6144/r^4>0$, so it is a minimum.'),A(r'$\boxed{k=3/2}$.')])])
add(79,'Exponential quadratic analysis','Stationary points and concavity',r'Let $f(x)=e^{-x}(x-3)^2$ for $x>0$.',[P('a',r'Show $f\prime(x)=-e^{-x}(x-3)(x-5)$.',[M(r'$f\prime=e^{-x}[2(x-3)-(x-3)^2]$.'),A(r'Factor to obtain $-e^{-x}(x-3)(x-5)$.')]),P('b',r'Find $f\prime\prime(x)$.',[A(r'$\boxed{f\prime\prime=e^{-x}(x^2-10x+23)}$.')]),P('c','Find and classify the stationary points exactly.',[M(r'$f\prime=0\Rightarrow x=3,5$.'),A(r'$f(3)=0$.'),A(r'$f(5)=4e^{-5}$.'),A(r'$f\prime\prime(3)=2e^{-3}>0$.'),A(r'$f\prime\prime(5)=-2e^{-5}<0$.'),R(r'$\boxed{(3,0)}$ is a minimum and $\boxed{(5,4e^{-5})}$ is a maximum.')]),P('d','Find the interval where $f$ is concave down.',[M(r'$x^2-10x+23<0$.'),M('Solve the corresponding quadratic equation.'),A(r'Roots $5\pm\sqrt2$.'),A(r'$\boxed{5-\sqrt2<x<5+\sqrt2}$.')]),P('e',r'If $g(3)=6$ and $g\prime(3)=4$, find $(f\circ g)\prime(3)$.',[M(r'Use $f\prime(g(3))g\prime(3)$.'),A(r'$f\prime(6)=-3e^{-6}$.'),A(r'$\boxed{-12e^{-6}}$.')])])
add(80,'A changing chord rectangle','Related rates',r'A rectangle has height equal to a fixed circle radius $r$ and width equal to a chord subtending angle $\theta$ at the centre, where $0<\theta<\pi$. Its area is $A$.',[P('a',r'Show $A=r\sqrt{2r^2(1-\cos\theta)}$.',[M(r'The cosine rule gives chord length $\sqrt{r^2+r^2-2r^2\cos\theta}$.'),A(r'Multiply by height $r$ to obtain $A=r\sqrt{2r^2(1-\cos\theta)}$.')]),P('b',r'Now $r=6$ cm and $d\theta/dt=1/3$ rad s$^{-1}$. Find $dA/dt$ at $\theta=\pi/3$ in the form $a\sqrt b$.',[M(r'Use $A=2r^2\sin(\theta/2)$ for $0<\theta<\pi$.'),M(r'$dA/dt=r^2\cos(\theta/2)\,d\theta/dt$.'),A(r'$36(\sqrt3/2)(1/3)=6\sqrt3$.'),A(r'$\boxed{dA/dt=6\sqrt3\text{ cm}^2\text{ s}^{-1}}$; $a=6,b=3$.')])])
s81=lambda z:(z-2)*math.sin(3*z);v81=lambda z:math.sin(3*z)+3*(z-2)*math.cos(3*z);a81=lambda z:6*math.cos(3*z)-9*(z-2)*math.sin(3*z)
rr81=roots(v81,0,3);tm81=max([0,3]+rr81,key=lambda z:abs(s81(z)));second81=rr81[1]
checked(81,'All velocity roots bracketed and displacement magnitude compared at roots/endpoints.',len(rr81)>=2 and all(abs(v81(z))<1e-8 for z in rr81))
add(81,'Distance from origin and second turn','Kinematics: differentiation',r'A particle’s displacement is $s(t)=t\sin(3t)-4\sin(3t/2)\cos(3t/2)$ centimetres for $0\le t\le3$.',[P('a','Find its maximum distance from the origin.',[M(r'$s(t)=(t-2)\sin(3t)$ and $v(t)=\sin(3t)+3(t-2)\cos(3t)$.'),M('Find the roots of $v$ and compare $|s|$ there and at both endpoints.'),A(f'The maximum is $\\boxed{{{abs(s81(tm81)):#.3g}\\text{{ cm}}}}$ at $t={tm81:.6f}$ s.')]),P('b','Find the acceleration at the second change of direction.',[M('Order the roots of $v$ at which its sign changes.'),A(f'The second occurs at $t={second81:.6f}$ s.'),M(r'$a(t)=6\cos(3t)-9(t-2)\sin(3t)$.'),A(f'$\\boxed{{a={a81(second81):#.3g}\\text{{ cm s}}^{{-2}}}}$.')])],calc=True)
add(82,'A logarithmic curve','Stationary points and concavity',r'Let $f(x)=2x\ln x-3x$ for $x>0$.',[P('a',r'Find $f(1)$.',[M(r'$f(1)=2\ln1-3$.'),A(r'$\boxed{-3}$.')]),P('b',r'Solve $f(x)=0$.',[M(r'$x(2\ln x-3)=0$.'),M(r'$x>0$, so $\ln x=3/2$.'),A(r'$\boxed{x=e^{3/2}}$.')]),P('c','Find and justify the local minimum.',[M(r'$f\prime=2\ln x-1$.'),A(r'$f\prime=0\Rightarrow x=\sqrt e$.'),A(r'$f(\sqrt e)=-2\sqrt e$.'),M(r'$f\prime\prime=2/x$.'),R(r'$f\prime\prime>0$, so $\boxed{(\sqrt e,-2\sqrt e)}$ is a minimum.')]),P('d','State where $f$ is increasing.',[M(r'$2\ln x-1>0$.'),A(r'$\boxed{x>\sqrt e}$.')]),P('e','Sketch $f$, showing its intercept and minimum.',[A(r'The graph approaches $(0,0)$ from below, but $x=0$ is excluded.'),A(r'Correct minimum at $(\sqrt e,-2\sqrt e)$ and crossing at $(e^{3/2},0)$.'),A('Concave up throughout; grows without bound as $x$ increases.')])],solutionDiagram=graph([(lambda z:2*z*math.log(z)-3*z,'#7a1f24')],(.01,7),(-5,8),[(math.sqrt(math.e),-2*math.sqrt(math.e),'Minimum'),(math.exp(1.5),0,'(e^(3/2), 0)')]))
add(83,'Surface area of an inflating sphere','Related rates',r'Air enters a spherical balloon at $24\text{ cm}^3\text{ min}^{-1}$. Given $S=4\pi r^2$ and $V=4\pi r^3/3$, find $dS/dt$ when $r=8$ cm.',[P('','',[M(r'$dS/dr=8\pi r$ and $dV/dr=4\pi r^2$.'),M(r'Chain rule: $dS/dt=(dS/dr)(dV/dt)/(dV/dr)$.'),A(r'$dS/dt=(2/r)\cdot24$.'),M('Substitute $r=8$.'),A(r'$\boxed{6\text{ cm}^2\text{ min}^{-1}}$.')])])
add(84,'Maximum trapezium in a semicircle','Optimization',r'An isosceles trapezium has its longer base along the diameter of a semicircle of radius 8 cm. The upper vertices lie on the arc at polar angles $\theta$ and $\pi-\theta$, where $0<\theta<\pi/2$.',[P('a',r'Show its area is $A=32(\sin2\theta+2\sin\theta)$.',[M(r'The bases are $16$ and $16\cos\theta$, and height is $8\sin\theta$.'),A(r'$A=\frac12(16+16\cos\theta)(8\sin\theta)=64\sin\theta(1+\cos\theta)$.'),A(r'Using $2\sin\theta\cos\theta=\sin2\theta$, $A=32(\sin2\theta+2\sin\theta)$.')]),P('b','Find the maximum area exactly.',[M(r'$A\prime=64(\cos2\theta+\cos\theta)=0$.'),A(r'$2\cos^2\theta+\cos\theta-1=0$ gives $\theta=\pi/3$ in the domain.'),R(r'$A\prime$ changes from positive to negative there.'),A(r'$\boxed{A_{\max}=48\sqrt3\text{ cm}^2}$.')])])
add(85,'Tangents at cubic stationary points','Stationary points and concavity',r'Let $f(x)=x^3/3+3x^2-16x+5$. Its horizontal tangents occur at $x=a$ and $x=b$, with $a<b$.',[P('a',r'Find $f\prime(x)$.',[M('Differentiate term by term.'),A(r'$f\prime=x^2+6x-16$.')]),P('b','Find $a$ and $b$.',[M(r'$x^2+6x-16=(x+8)(x-2)=0$.'),A(r'$a=-8$.'),A(r'$b=2$.')]),P('c',r'Sketch $f\prime$ and use it to explain the maximum at $x=a$.',[A('An upward parabola with zeros $-8,2$ and negative between them.'),R(r'$f\prime$ changes from positive to negative at $-8$, hence $f$ has a maximum.')]),P('d',r'Find $f\prime\prime(b)$ and use it to justify the minimum at $b$.',[M(r'$f\prime\prime=2x+6$.'),M(r'Substitute $b=2$.'),A(r'$f\prime\prime(2)=10$.'),R('This is positive, so the stationary point is a minimum.')]),P('e','The tangent at $a$ and normal at $b$ intersect at $(p,q)$. Find $p,q$.',[M('The tangent at $a$ is horizontal.'),A(r'$f(-8)=463/3$, so its equation is $y=463/3$.'),M('The tangent at $b$ is horizontal, so its normal is vertical.'),A(r'The normal is $x=2$.'),A(r'$\boxed{p=2,\ q=463/3}$.')])])
add(86,'A varying triangle','Optimization',r'Triangle $ABC$ has $\angle BAC=60^\circ$, $AB=(2-x)$ cm and $AC=(x+4)^2$ cm, where $-4<x<2$.',[P('a',r'Show its area is $A=\frac{\sqrt3}{4}(2-x)(x+4)^2$.',[M(r'$A=\frac12 AB\cdot AC\sin60^\circ$.'),A(r'$A=\frac{\sqrt3}{4}(2-x)(x+4)^2$.')]),P('b',r'Find $dA/dx$ and verify it is zero at $x=0$.',[M('Differentiate the product.'),A(r'$A\prime=-\frac{3\sqrt3}{4}x(x+4)$.'),A(r'$A\prime(0)=0$.')]),P('c','Justify that $x=0$ gives the maximum area, find that area, and find $BC$ then.',[M(r'$A\prime\prime=-\frac{3\sqrt3}{2}(x+2)$.'),R(r'$A\prime\prime(0)=-3\sqrt3<0$; area is zero at both limiting endpoints, so this is the global maximum.'),A(r'$\boxed{A_{\max}=8\sqrt3\text{ cm}^2}$.'),A(r'At $x=0$, $AB=2$ and $AC=16$.'),M('Use the cosine rule for $BC$.'),A(r'$BC^2=2^2+16^2-2(2)(16)\cos60^\circ=228$.'),A(r'$\boxed{BC=2\sqrt{57}\text{ cm}}$.')])])
add(87,'A parameterized cosine limit','L’Hôpital’s rule',r'Let $f(x)=[\cos(mx)-\cos(nx)]/x^2$. Assume $0<m<n$ and define $f(0)$ by continuity. It is known that its maximum value is $f(0)$.',[P('a',r'Show $f_{\max}=(n^2-m^2)/2$.',[R('The initial form is $0/0$.'),M('Apply L’Hôpital once.'),A(r'$\lim[-m\sin(mx)+n\sin(nx)]/(2x)$.'),R('The new form is $0/0$.'),M('Apply L’Hôpital again.'),A(r'$f_{\max}=\lim[-m^2\cos(mx)+n^2\cos(nx)]/2=(n^2-m^2)/2$.')]),P('b',r'Given $m>0$ and $n=6\sqrt m$, find the largest possible $f_{\max}$.',[M(r'$f_{\max}=(36m-m^2)/2=162-(m-18)^2/2$.'),A(r'The largest possible value is $\boxed{162}$ at $m=18$.')])])
add(88,'A tangent through a maximum','Tangents and normals',r'Let $f(x)=x^3+3x^2+kx-4$. Its tangent $L$ at the $y$-intercept $Q$ also passes through a distinct local maximum point $P$.',[P('a','Find $Q$.',[M(r'Set $x=0$.'),A(r'$\boxed{Q=(0,-4)}$.')]),P('b',r'Find $f\prime$ and the equation of $L$ in terms of $k$.',[M('Differentiate.'),A(r'$f\prime=3x^2+6x+k$.'),A(r'$f\prime(0)=k$.'),A(r'$\boxed{L:y=kx-4}$.')]),P('c','Find $k$.',[M(r'Points common to $L$ and $f$ satisfy $x^3+3x^2=0$.'),A(r'$x^2(x+3)=0$.'),A(r'The distinct point $P$ has $x=-3$.'),M(r'At a maximum, $f\prime(-3)=0$.'),A(r'$27-18+k=0\Rightarrow k=-9$.'),R(r'$f\prime\prime(-3)=-12<0$, so $\boxed{k=-9}$ gives the required maximum.')])])
add(89,'A third-order inverse-tangent limit','L’Hôpital’s rule',r'Use L’Hôpital’s rule to find $\displaystyle\lim_{x\to0}\frac{7(x-\arctan x)}{x^3}$.',[P('','',[R('The initial form is $0/0$.'),M('Differentiate numerator and denominator.'),A(r'$\lim\frac{7(1-1/(1+x^2))}{3x^2}$.'),M(r'Combine the terms inside the numerator.'),A(r'$\lim\frac{7x^2}{3x^2(1+x^2)}$.'),M(r'Cancel $x^2$ for $x\ne0$, then take the limit.'),A(r'$\boxed{7/3}$.')])])
h90=1536**.1;checked(90,'Horizontal-tangent solution satisfies the implicit curve.',abs(h90**5+(h90**3/4)**5-10*h90*h90*(h90**3/4))<1e-7)
add(90,'A vertical normal to an implicit curve','Implicit differentiation',r'Consider $x^5+y^5=10x^2y$.',[P('a',r'Show $dy/dx=(4xy-x^4)/(y^4-2x^2)$.',[M(r'$5x^4+5y^4y\prime=20xy+10x^2y\prime$.'),M('Collect $y\prime$ terms and divide by 5.'),A(r'$\boxed{y\prime=(4xy-x^4)/(y^4-2x^2)}$.')]),P('b','The normal is vertical at a point with $x=h>0$. Find $h$ to two decimal places.',[M(r'The tangent is horizontal, so $4xy-x^4=0$.'),A(r'$y=x^3/4$.'),M('Substitute in the original curve.'),A(r'$x^5+x^{15}/1024=(5/2)x^5\Rightarrow x^{10}=1536$.'),A(f'$\\boxed{{h={h90:.2f}}}$; the derivative denominator is nonzero there.')])],calc=True)
add(91,'A periodic swimming model','Trigonometric differentiation',r'A swimmer’s speed between successive turns is modelled by $v(t)=-0.6\cos(\pi(t-3)/12)+2.4$ metres per second for $t\ge0$. Each minimum of this model marks a turn at a wall; consecutive turns are at opposite walls. Time is in seconds.',[P('a','Find the maximum speed and when it is first reached.',[M('Maximum speed occurs when cosine is $-1$.'),A(r'$v_{\max}=3\text{ m s}^{-1}$.'),M(r'$\pi(t-3)/12=\pi$ for the first nonnegative maximum time.'),A(r'$\boxed{t=15\text{ s}}$.')]),P('b','Find the number of turns in the first two minutes.',[M(r'Minima occur at $t=3+24n$.'),A(r'Times are $3,27,51,75,99$ seconds.'),A(r'$\boxed{5\text{ turns}}$.')]),P('c','Find $v\prime(t)$ and the maximum rate of increase of speed.',[M('Differentiate the speed model.'),A(r'$v\prime(t)=\frac\pi{20}\sin(\pi(t-3)/12)$.'),A(r'Maximum rate $\boxed{\pi/20\text{ m s}^{-2}}$.')]),P('d','Find the pool length.',[M('Integrate speed over one interval between consecutive turns, e.g. $3\le t\le27$.'),A(r'An antiderivative is $-\frac{7.2}{\pi}\sin(\pi(t-3)/12)+2.4t$.'),A('The sine contribution vanishes at both limits.'),A(r'$\boxed{2.4(27-3)=57.6\text{ m}}$.')])])
add(92,'The optimal stadium enclosure','Optimization',r'An enclosure consists of a rectangle of length $L$ and width $2r$, with a semicircle of radius $r$ attached to each short side. The total perimeter is 420 m. The limiting case $L=0$ is permitted.',[P('a','Find the area in terms of $r$ and the width when area is maximal.',[M(r'$2L+2\pi r=420$.'),A(r'$L=210-\pi r$.'),M(r'Area is $2rL+\pi r^2$.'),A(r'$A=420r-\pi r^2$, $0<r\le210/\pi$.'),M(r'$A\prime=420-2\pi r$.'),A(r'$A\prime=0$ at $r=210/\pi$.'),R(r'$A\prime\prime=-2\pi<0$ and the radius is allowed.'),M('Width is $2r$.'),A(r'$\boxed{\text{width}=420/\pi\text{ m}}$.')]),P('b','Show that the optimum is a circle.',[M(r'$L=210-\pi(210/\pi)=0$.'),A(r'The two semicircles form one circle of radius $\boxed{210/\pi\text{ m}}$.')])])
add(93,'Two tangents related by composition','Product and chain rules',r'The line $L_1:y=2x+3$ is tangent to $f$ at $x=5$. Let $g(x)=f(x^2+1)$, and let $P$ be the point on $g$ with $x=2$.',[P('a',r'Find $f\prime(5)$ and $f(5)$.',[M('Read the tangent gradient.'),A(r'$f\prime(5)=2$.'),M(r'Substitute $x=5$ in $L_1$.'),A(r'$f(5)=13$.')]),P('b','Show that $g$ has gradient 8 at $P$.',[M(r'Apply the chain rule: $g\prime(x)=2x f\prime(x^2+1)$.'),A(r'At $x=2$, the inner argument is $5$.'),A(r'$f\prime(5)=2$.'),M(r'Multiply by $2x=4$.'),A(r'$g\prime(2)=4\cdot2=8$.')]),P('c','The tangent $L_2$ to $g$ at $P$ meets $L_1$ at $Q$. Find the $y$-coordinate of $Q$.',[M(r'$g(2)=f(5)$.'),A(r'$P=(2,13)$.'),M('Use the tangent gradient from (b).'),A(r'$L_2:y-13=8(x-2)$.'),A(r'$L_2:y=8x-3$.'),M(r'Solve $2x+3=8x-3$.'),A(r'$x=1$ at $Q$.'),A(r'$\boxed{y_Q=5}$.')])])
add(94,'A parameterized rational curve','Stationary points and concavity',r'Let $f(x)=\dfrac{x^2-(a+4)x+4a}{x-3}$, where $x\ne3$ and $a\in\mathbb R$.',[P('a','For $a=5$, find the vertical and oblique asymptotes, justify that there are two stationary points, and sketch the curve showing its intercepts.',[M(r'$f=x-6+2/(x-3)$.'),A(r'Vertical asymptote $x=3$.'),A(r'Oblique asymptote $y=x-6$.'),M(r'$f\prime=1-2/(x-3)^2$.'),R(r'$f\prime=0$ gives two allowed roots $3\pm\sqrt2$.'),A(r'$x$-intercepts $(4,0),(5,0)$.'),A(r'$y$-intercept $(0,-20/3)$.'),A(r'Left branch maximum $(3-\sqrt2,-3-2\sqrt2)$; right branch minimum $(3+\sqrt2,-3+2\sqrt2)$.'),A('Sketch two branches approaching the stated asymptotes and passing through those features.')]),P('b','Show that $f$ always has at least one root.',[M(r'The numerator factors as $(x-a)(x-4)$.'),A(r'$x=4$ is a root for every $a$.'),R(r'$4\ne3$, so it is always in the domain.')]),P('c','Find all $a$ for which there are no stationary points.',[M(r'$f=x-a-1+(a-3)/(x-3)$.'),A(r'$f\prime=1-(a-3)/(x-3)^2$.'),M(r'Stationary points require $(x-3)^2=a-3>0$.'),A(r'Thus there are none when $\boxed{a\le3}$.')]),P('d',r'For $a\ne3$, show that the root of the oblique asymptote is exactly 1 unit from a root of $f$.',[M(r'The oblique asymptote is $y=x-a-1$.'),A(r'Its root is $x=a+1$.'),A(r'$x=a$ is a root of $f$ because $a\ne3$.'),R(r'The separation is $|(a+1)-a|=1$. The exclusion is essential when numerator and denominator cancel.')])])
add(95,'Tangents to an exponential implicit curve','Implicit differentiation',r'A curve satisfies $3y^2e^{x+2}-4x^2=11$.',[P('a',r'Find $dy/dx$.',[M(r'$6yy\prime e^{x+2}+3y^2e^{x+2}-8x=0$.'),M('Isolate $y\prime$.'),A(r'$\boxed{y\prime=\frac{8x-3y^2e^{x+2}}{6ye^{x+2}}}$.')]),P('b','Find both tangents at $x=-2$.',[M(r'$3y^2-16=11\Rightarrow y=\pm3$.'),A(r'The gradients are $-43/18$ at $y=3$ and $43/18$ at $y=-3$.'),A(r'$\boxed{y-3=-\frac{43}{18}(x+2)}$.'),A(r'$\boxed{y+3=\frac{43}{18}(x+2)}$.')])])
rr96=roots(lambda z:math.cos(2*z+1)+z-5,0,10)
intervals96=[]
for k in range(-2,6):
 lo=(math.pi/6+2*k*math.pi-1)/2;hi=(5*math.pi/6+2*k*math.pi-1)/2
 lo=max(0,lo);hi=min(10,hi)
 if hi>lo:intervals96.append((lo,hi))
duration96=sum(b-a for a,b in intervals96)
checked(96,'Intersections bracketed; velocity inequality duration computed from all trigonometric intervals.',all(abs(math.cos(2*z+1)+z-5)<1e-8 for z in rr96))
add(96,'Comparing two particle motions','Kinematics: differentiation',r'Two particles have displacements $s_A(t)=6t+8$ and $s_B(t)=\cos(2t+1)+7t+3$ centimetres for $0\le t\le10$ seconds.',[P('a','Find their initial displacements, to three significant figures where needed.',[A(r'$s_A(0)=8$ cm.'),M(r'$s_B(0)=\cos1+3$.'),A(r'$\boxed{s_B(0)=3.54\text{ cm}}$.')]),P('b','Find all times when their displacements are equal.',[M(r'Solve $\cos(2t+1)+t-5=0$.'),M('Find all roots on $[0,10]$ graphically or numerically.'),A('$\\boxed{t='+',\ '.join(f'{z:#.3g}' for z in rr96)+'\\text{ s}}$.')]),P('c','Prove B is farther from the origin than A whenever $6<t\le10$.',[M(r'$s_B-s_A=\cos(2t+1)+t-5$.'),R(r'$\cos(2t+1)\ge-1$, so $s_B-s_A\ge t-6>0$.'),R(r'Both displacements are positive on this interval; hence B’s distance is larger.')]),P('d','Find the total time for which A’s velocity exceeds B’s.',[M(r'$v_A=6$, $v_B=7-2\sin(2t+1)$.'),A(r'$v_A>v_B\iff\sin(2t+1)>1/2$.'),M(r'The phase intervals are $(\pi/6+2k\pi,5\pi/6+2k\pi)$.'),M('Convert to time intervals and intersect with $[0,10]$.'),A('Relevant time intervals (seconds): '+', '.join(f'$({a:.6f},{b:.6f})$' for a,b in intervals96)+'.'),A(f'Total duration $\\boxed{{{duration96:#.3g}\\text{{ s}}}}$.')])],calc=True)
add(97,'Orthogonal implicit curves','Implicit differentiation',r'The curves $C_1:3y^2+2x^2=23$ and $C_2:y^2=7x^3$ have $y>0$. They meet at $P$.',[P('a',r'Find $dy/dx$ for each curve.',[M(r'For $C_1$, $6yy\prime+4x=0$.'),A(r'$m_1=-2x/(3y)$.'),M(r'For $C_2$, $2yy\prime=21x^2$.'),A(r'$m_2=21x^2/(2y)$.')]),P('b','Show their tangents at $P$ are perpendicular.',[M(r'$m_1m_2=-7x^3/y^2$.'),A(r'At the intersection, $y^2=7x^3$, so $m_1m_2=-1$.'),R('The gradients are finite and nonzero since $x,y>0$, hence the tangents are perpendicular.')])])
add(98,'A sliding ladder','Related rates',r'A 17 m ladder rests against a vertical wall on level ground. Its foot moves away from the wall at $1.5\text{ m s}^{-1}$. Find the speed at which its top descends when the foot is 8 m from the wall.',[P('','',[M(r'Let horizontal and vertical distances be $x,y$: $x^2+y^2=289$.'),A(r'At $x=8$, $y=\sqrt{289-64}=15$.'),M('Differentiate with respect to time.'),A(r'$2x\,dx/dt+2y\,dy/dt=0$.'),M(r'$dy/dt=-(x/y)\,dx/dt$.'),A(r'$dy/dt=-(8/15)(1.5)=-0.8\text{ m s}^{-1}$.'),A(r'The speed of descent is $\boxed{0.800\text{ m s}^{-1}}$.')])])
add(99,'Changing distance from a nest','Related rates',r'A bird is 5 km east and 12 km north of its nest. At that instant it flies east at $16\text{ km h}^{-1}$ and north at $20\text{ km h}^{-1}$. Find the rate of change of its distance from the nest.',[P('','',[M(r'Let $r^2=x^2+y^2$.'),A(r'$r=\sqrt{25+144}=13$ km.'),M('Differentiate with respect to time.'),A(r'$2r\,dr/dt=2x\,dx/dt+2y\,dy/dt$.'),M(r'$dr/dt=[5(16)+12(20)]/13$.'),A(r'$dr/dt=320/13$.'),A(r'$\boxed{24.6\text{ km h}^{-1}}$, increasing.')])],calc=True)
save()
# Hard questions 100–126.
add(100,'Lines through an inflexion point','Stationary points and concavity',r'Let $f(x)=4xe^x+2$. Its unique inflexion point is $A$. Every line $g(x)=mx+c$ considered below passes through $A$.',[P('a','Show the inflexion occurs at $x=-2$.',[M(r'$f\prime=4e^x(x+1)$ and $f\prime\prime=4e^x(x+2)$.'),A(r'$f\prime\prime=0$ only at $x=-2$.'),R(r'$e^x>0$, so $f\prime\prime$ changes from negative to positive there.')]),P('b','Sketch $f$, labelling $A$ and its horizontal asymptote.',[A(r'Sketch with $A=(-2,2-8e^{-2})$, horizontal asymptote $y=2$ as $x\to-\infty$, minimum $(-1,2-4/e)$, and rapid increase to the right.')]),P('c','Find the slope of the tangent at $A$, then the range of $m$ for which $f(x)=g(x)$ has exactly three distinct solutions.',[A(r'The tangent slope is $f\prime(-2)=-4e^{-2}$.'),M(r'For $H=f-g$, $H(-2)=0$ and $H\prime=f\prime-m$. A line slope strictly between the minimum derivative and 0 gives two turning points of $H$, straddling $-2$.'),R(r'Then $H$ crosses at $-2$, has positive and negative extrema on either side, and tends to $-\infty$ on the far left and $+\infty$ on the far right. Boundary slopes give fewer distinct intersections.'),A(r'$\boxed{-4e^{-2}<m<0}$.')])],solutionDiagram=graph([(lambda z:4*z*math.exp(z)+2,'#7a1f24')],(-5,1.2),(-.1,10),[(-2,2-8/math.e**2,'A'),(-1,2-4/math.e,'Minimum'),(0,2,'(0, 2)')]))
checked(101,'First-quadrant folium horizontal tangent satisfies curve and numerator equation.',s.simplify(((s.Rational(9,4))**2+(9*s.sqrt(3)/4)**2)**2-12*s.Rational(9,4)*(9*s.sqrt(3)/4)**2)==0)
add(101,'Horizontal tangent to a double folium','Implicit differentiation',r'The curve $(x^2+y^2)^2=12xy^2$ has a point $P$ in the first quadrant where the tangent is horizontal. Find the exact coordinates of $P$.',[P('','',[M(r'Implicit differentiation gives $2(x^2+y^2)(2x+2yy\prime)=12y^2+24xyy\prime$.'),A(r'$y\prime=\frac{12y^2-4x(x^2+y^2)}{4y(x^2+y^2)-24xy}$.'),M(r'For a horizontal tangent, $3y^2=x(x^2+y^2)$.'),M(r'Let $u=x^2+y^2>0$. Combining $y^2=xu/3$ and $u^2=12xy^2$ gives $u=4x^2$.'),A(r'Thus $y^2=3x^2$.'),M(r'$3(3x^2)=x(4x^2)$ and $x>0$ imply $x=9/4$.'),A(r'$y=9\sqrt3/4$ in the first quadrant.'),R(r'The derivative denominator is nonzero there, so $\boxed{P=(9/4,9\sqrt3/4)}$.')])])
add(102,'A zero second derivative is not enough','Stationary points and concavity',r'Let $h(x)=\cos(2\pi\cos x)$ for $-\pi\le x\le\pi$.',[P('a','Determine whether $h$ is even, odd or neither.',[M(r'$h(-x)=\cos(2\pi\cos(-x))=\cos(2\pi\cos x)$.'),A(r'$\boxed{h\text{ is even}}$.')]),P('b',r'Show that $h\prime\prime(0)=0$.',[M(r'$h\prime=2\pi\sin x\sin(2\pi\cos x)$.'),M('Differentiate using the product and chain rules.'),A(r'$h\prime\prime=2\pi\cos x\sin(2\pi\cos x)-4\pi^2\sin^2x\cos(2\pi\cos x)$.'),A(r'At $x=0$, both terms vanish since $\sin2\pi=\sin0=0$.')]),P('c',r'A student claims $(0,1)$ must therefore be an inflexion point. Explain whether this is correct.',[R(r'$h\prime\prime$ is even, so its values at $x$ and $-x$ have the same sign.'),R('There is no change of concavity across 0. A zero second derivative alone does not establish an inflexion point; the claim is false.')])])
x103=.6;y103=math.sqrt((1-x103*x103)/(15-12*x103*x103));dy103=180*x103*(12*y103*y103-1)/(y103*(15-12*x103*x103))
checked(103,'Point and implicit related rate checked by differentiating the explicit positive branch.',abs((math.sqrt((1-(x103+1e-6)**2)/(15-12*(x103+1e-6)**2))-math.sqrt((1-(x103-1e-6)**2)/(15-12*(x103-1e-6)**2)))/(2e-6)*180-dy103)<1e-5)
add(103,'Motion along an oval track','Related rates',r'A track is described by $x^2+15y^2=1+12x^2y^2$, with distances in kilometres. A car is on the upper half ($y>0$), moving with $dx/dt=180\text{ km h}^{-1}$ when $x=0.60$ km. Find $dy/dt$ to the nearest kilometre per hour.',[P('','',[M(r'Differentiate with respect to time: $2x\dot x+30y\dot y=24xy^2\dot x+24x^2y\dot y$.'),A(r'$\dot y=\frac{x(12y^2-1)}{y(15-12x^2)}\dot x$.'),M(r'From the original equation, $y^2=(1-x^2)/(15-12x^2)$.'),A(f'At $x=0.60$, $y={y103:.8f}$ km, taking the positive root.'),M('Substitute this value and $\dot x=180$ without premature rounding.'),A(f'$\\boxed{{dy/dt={round(dy103)}\\text{{ km h}}^{{-1}}}}$.')])],calc=True)
add(104,'Restricting an exponential for inversion','Inverse functions and differentiation',r'Let $f(x)=e^{2x}-6e^x+5$ on $x\le a$.',[P('a','Find the largest $a$ for which $f$ has an inverse.',[M(r'$f\prime=2e^x(e^x-3)$.'),R(r'$f\prime<0$ for $x<\ln3$ and $f\prime>0$ for $x>\ln3$; including any interval past the minimum destroys injectivity on this left-unbounded domain.'),A(r'$\boxed{a=\ln3}$.')]),P('b','For this $a$, find $f^{-1}$ and its domain.',[M(r'Write $y=(e^x-3)^2-4$.'),A(r'$e^x=3\pm\sqrt{y+4}$.'),R(r'$x\le\ln3$ implies $e^x\le3$, selecting the minus sign.'),A(r'$\boxed{f^{-1}(x)=\ln(3-\sqrt{x+4})}$.'),A(r'Domain $\boxed{-4\le x<5}$; the endpoint 5 is only a limiting value of $f$.')])])
add(105,'Stationary points of a nested cosine','Trigonometric differentiation',r'Find all points on $y=\cos(3\pi\cos x)$ for which $dy/dx=0$ on $0\le x\le\pi$.',[P('','',[M('Apply the chain rule twice.'),A(r'$y\prime=3\pi\sin x\sin(3\pi\cos x)$.'),M(r'Either $\sin x=0$ or $\sin(3\pi\cos x)=0$.'),A(r'The second case gives $\cos x=k/3$, $k=-3,-2,-1,0,1,2,3$; endpoints from the first case are already included.'),A(r'For each $k$, $y=\cos(k\pi)=(-1)^k$.',1),A(r'Points: $(0,-1)$, $(\arccos(2/3),1)$, $(\arccos(1/3),-1)$.',1),A(r'Also $(\pi/2,1)$, $(\arccos(-1/3),-1)$, $(\arccos(-2/3),1)$.',1),A(r'Finally $(\pi,-1)$. These are all seven distinct points.',1)])])
f106=2*x**4-s.Rational(56,3)*x**3+56*x*x-60*x
checked(106,'Parallel-tangent cubic factors exactly and supplied point lies on the curve.',s.expand(s.diff(f106,x)-4-8*(x-1)*(x-2)*(x-4))==0 and f106.subs(x,1)==-s.Rational(62,3))
add(106,'Parallel tangents to a quartic','Tangents and normals',r'Find the $x$-coordinates where the tangent to $y=2x^4-\frac{56}{3}x^3+56x^2-60x$ is parallel to its tangent at $P(1,-62/3)$. Include $P$ itself.',[P('','',[M('Differentiate.'),A(r'$y\prime=8x^3-56x^2+112x-60$.'),A(r'The gradient at $x=1$ is $4$.'),M(r'Solve $8x^3-56x^2+112x-60=4$.'),A(r'$x^3-7x^2+14x-8=0$.'),M(r'Factor as $(x-1)(x-2)(x-4)=0$.'),A(r'$\boxed{x=1,2,4}$.')])])
A107=50*s.acos((10-h)/10)+(h-10)*s.sqrt(20*h-h*h)/2
checked(107,'Segment area derivative simplifies to the width of a vertical slice.',s.simplify(s.diff(A107,h)-s.sqrt(20*h-h*h))==0)
add(107,'Water depth in a circular gutter','Related rates',r'In a quarter circle of radius 10 cm, $O=(0,0)$, $A=(0,10)$ and $B=(10,0)$. A vertical line through $C=(10-h,0)$ meets the arc at $D$. The region $CBD$ is bounded by $CB$, $CD$ and the arc $BD$, with $0<h<10$.',[P('a','Find $OC$ and $CD$ in terms of $h$.',[A(r'$OC=10-h$.'),M(r'$CD^2=10^2-(10-h)^2$.'),A(r'$\boxed{CD=\sqrt{20h-h^2}}$.')]),P('b',r'Show that the area is $A(h)=50\arccos((10-h)/10)+\frac12(h-10)\sqrt{20h-h^2}$.',[M(r'Let $\theta=\arccos((10-h)/10)$.'),A(r'Sector $OBD$ has area $\frac12(10)^2\theta=50\theta$.'),M(r'Triangle $OCD$ has area $\frac12(10-h)\sqrt{20h-h^2}$.'),M('Subtract the triangle from the sector.'),A(r'$A(h)=50\arccos((10-h)/10)+\frac12(h-10)\sqrt{20h-h^2}$.')]),P('c',r'A gutter has this cross-section, oriented so that $CB$ is vertical and $CD$ is the water surface. Its length is 1.2 m. Water drains at $300\sqrt h\text{ cm}^3\text{ s}^{-1}$. Find $dh/dt$ when $h=4$ cm.',[M('Convert the length to 120 cm and write $V=120A(h)$.'),M(r'Differentiate the arccosine term: $50/\sqrt{20h-h^2}$.'),M('Apply the product rule to the second term.'),A(r'$A\prime=\frac{50}{\sqrt{20h-h^2}}+\frac12\sqrt{20h-h^2}-\frac{(10-h)^2}{2\sqrt{20h-h^2}}$.'),A(r'This simplifies to $A\prime=\sqrt{20h-h^2}$.'),M(r'$dV/dt=120\sqrt{20h-h^2}\,dh/dt$.'),A(r'At $h=4$, $dV/dt=-600$ and $\sqrt{20h-h^2}=8$.'),M(r'$-600=960\,dh/dt$.'),A(r'$\boxed{dh/dt=-5/8\text{ cm s}^{-1}}$.')])])
add(108,'Stationary points of a nested sine','Trigonometric differentiation',r'Find all points on $y=\cos(3\pi\sin x)$ for which $dy/dx=0$ on $0\le x\le\pi$.',[P('','',[M(r'$y\prime=-3\pi\cos x\sin(3\pi\sin x)$.'),M(r'Either $\cos x=0$ or $3\pi\sin x=k\pi$.'),A(r'$x=\pi/2$, or $\sin x=k/3$ with $k=0,1,2,3$.'),A(r'$k=0$ gives $(0,1),(\pi,1)$.'),A(r'$k=1$ gives $(\arcsin(1/3),-1),(\pi-\arcsin(1/3),-1)$.'),A(r'$k=2$ gives $(\arcsin(2/3),1),(\pi-\arcsin(2/3),1)$.'),A(r'$k=3$ gives $(\pi/2,-1)$, already counted by $\cos x=0$. These are all seven points.')])])
checked(109,'Given point and both parallel-tangent points satisfy the implicit curve.',all(X*X+8*X*Y+Y*Y==40 for X,Y in [(-2,18),(2,2),(-2,-2)]))
add(109,'Normals and distance on a rotated conic','Implicit differentiation',r'A curve satisfies $x^2+8xy+y^2=40$.',[P('a',r'Show $dy/dx=-(2x+8y)/(8x+2y)$.',[M(r'$2x+8(y+xy\prime)+2yy\prime=0$.'),M('Collect derivative terms.'),A(r'$y\prime=-(2x+8y)/(8x+2y)$.')]),P('b','Find the normal at $P(-2,18)$.',[M('Substitute the coordinates in the derivative.'),A(r'The tangent gradient is $-140/20=-7$.'),M(r'The normal gradient is $1/7$.'),A(r'$\boxed{y-18=\frac17(x+2)}$.')]),P('c',r'Find the distance between the two points whose tangents are parallel to $y=-x$.',[M(r'Set $-(2x+8y)/(8x+2y)=-1$.'),A(r'$2x+8y=8x+2y\Rightarrow y=x$.'),M('Substitute into the curve.'),A(r'$10x^2=40$.'),A(r'The points are $(2,2)$ and $(-2,-2)$.'),M('Use the distance formula.'),A(r'$\boxed{\sqrt{4^2+4^2}=4\sqrt2}$.')])])
add(110,'Water surface in a hemispherical bowl','Related rates',r'A hemispherical bowl has radius 8 cm. Water enters at $3\pi\text{ cm}^3\text{ s}^{-1}$. When water depth is $h$, its volume is $V=\pi h^2(24-h)/3$. Let $A$ be the area of its flat circular surface. Find $dA/dt$ when $h=3$ cm.',[P('','',[M(r'If the water surface radius is $r$, $r^2+(8-h)^2=64$.'),A(r'$r^2=16h-h^2$.'),A(r'$A=\pi(16h-h^2)$.'),M('Differentiate the supplied volume formula.'),A(r'$dV/dh=\pi h(16-h)$.'),M(r'At $h=3$, $dh/dt=(3\pi)/(39\pi)=1/13$.'),M(r'$dA/dt=\pi(16-2h)\,dh/dt$.'),M('Substitute $h=3$ and $dh/dt=1/13$.'),A(r'$\boxed{dA/dt=10\pi/13\text{ cm}^2\text{ s}^{-1}}$.')])])
add(111,'Proving absence of local extrema','Implicit differentiation',r'For $x>0$ and $y>0$, a curve is defined by $(x^2+y^2)(y^2-16)+16y^2=0$. Show that it has no local maximum or minimum points.',[P('','',[M(r'Expand to $x^2(y^2-16)+y^4=0$.'),R(r'$x^2(16-y^2)=y^4>0$, so $0<y<4$.'),M(r'Differentiate: $2x(y^2-16)+(2x^2y+4y^3)y\prime=0$.'),A(r'$y\prime=\frac{x(16-y^2)}{y(x^2+2y^2)}$.'),R('The numerator is positive on the given curve.'),R('The denominator is positive, so the derivative exists and is strictly positive.'),R('Thus the curve is locally strictly increasing everywhere on its stated domain, with no local maximum or minimum.')])])
add(112,'Logarithms, convexity and an inequality','Stationary points and concavity',r'Let $f(x)=(3x-12)\ln(x+4)+2x$ on its maximal real domain $x>p$.',[P('a','Find $p$.',[M(r'The logarithm requires $x+4>0$.'),A(r'$\boxed{p=-4}$.')]),P('b',r'Find $f\prime(x)$.',[M('Use the product rule.'),A(r'$f\prime=3\ln(x+4)+(3x-12)/(x+4)+2$.'),A(r'$\boxed{f\prime=3\ln(x+4)+5-24/(x+4)}$.')]),P('c','Determine the concavity on the whole domain.',[M(r'$f\prime\prime=3/(x+4)+24/(x+4)^2$.'),A(r'$f\prime\prime=3(x+12)/(x+4)^2$.'),R(r'It is positive for $x>-4$, so $f$ is concave up everywhere on its domain.')]),P('d',r'Let $g(x)=4\ln(1/(x+4))+2x$, $x>-4$. Find $g\prime(x)$.',[M(r'Rewrite $g=-4\ln(x+4)+2x$.'),M('Differentiate the logarithm.'),A(r'The logarithmic contribution is $-4/(x+4)$.'),A(r'$\boxed{g\prime=2-4/(x+4)}$.')]),P('e',r'Find the horizontal and vertical asymptotes of $g\prime$.',[A(r'$\boxed{y=2}$.'),A(r'$\boxed{x=-4}$.')]),P('f','Find the exact minimum value of $g$.',[M(r'$2-4/(x+4)=0\Rightarrow x=-2$.'),R(r'$g\prime\prime=4/(x+4)^2>0$.'),A(r'$\boxed{g_{\min}=-4\ln2-4}$.')]),P('g',r'Solve $f(x)<g(x)$.',[M(r'$f-g=(3x-8)\ln(x+4)$.'),A(r'The zeros are $x=-3$ and $x=8/3$.'),M('Analyze signs on the three intervals within $x>-4$.'),A(r'The product is positive on $(-4,-3)$, negative on $(-3,8/3)$, and positive thereafter.'),A(r'$\boxed{-3<x<8/3}$.')])])
add(113,'Choosing a constant for a finite limit','L’Hôpital’s rule',r'Consider $\displaystyle\lim_{x\to0}\frac{3\arctan(e^{2x})-c}{5x}$, where $c\in\mathbb R$.',[P('a','Show that a finite limit requires $c=3\pi/4$.',[M(r'The numerator tends to $3\arctan1-c=3\pi/4-c$ while the denominator tends to zero.'),R(r'A finite limit requires the numerator limit to vanish, so $c=3\pi/4$.')]),P('b','For this constant, use L’Hôpital’s rule to evaluate the limit.',[R('The expression now has form $0/0$.'),M('Differentiate numerator and denominator.'),A(r'The quotient becomes $[6e^{2x}/(1+e^{4x})]/5$.'),A(r'At $x=0$, this is $\boxed{3/5}$.')])])
add(114,'Logarithmic differentiation and a limit','L’Hôpital’s rule',r'Let $y=x^{-3x}$ for $x>0$.',[P('a',r'Show $dy/dx=-3x^{-3x}(\ln x+1)$.',[M(r'$\ln y=-3x\ln x$.'),M(r'$y\prime/y=-3(\ln x+1)$.'),A(r'$y\prime=-3x^{-3x}(\ln x+1)$.')]),P('b',r'Hence evaluate $\displaystyle\lim_{x\to1}\frac{1-(1/x^3)^x}{(2/3)x(x-1)}$.',[R('The form is $0/0$.'),M(r'Use part (a) and L’Hôpital’s rule.'),A(r'The differentiated quotient is $\frac{3x^{-3x}(\ln x+1)}{(2/3)(2x-1)}$.'),A(r'At $x=1$, the limit is $3/(2/3)=\boxed{9/2}$.')])])
checked(115,'Indeterminate and integral-ratio limiting value verified symbolically.',s.limit((s.exp(-4*x*x)-2*s.cos(4*x)+1)/(3*x*x),x,0)==4)
add(115,'A limit and its integral counterpart','L’Hôpital’s rule',r'Consider the following limits.',[P('a',r'Use L’Hôpital’s rule to find $\displaystyle\lim_{x\to0}\frac{e^{-4x^2}-2\cos(4x)+1}{3x^2}$.',[R('The form is $0/0$.'),M('Differentiate once.'),A(r'$\lim[-8xe^{-4x^2}+8\sin(4x)]/(6x)$.'),M('The form remains $0/0$; differentiate again.'),A(r'$\lim[(64x^2-8)e^{-4x^2}+32\cos(4x)]/6$.'),A(r'The limit is $(-8+32)/6=\boxed4$.')]),P('b',r'Hence find $\displaystyle\lim_{x\to0}\frac{\int_0^x(e^{-4t^2}-2\cos(4t)+1)\,dt}{\int_0^x3t^2\,dt}$.',[R('Both integrals tend to zero.'),M('L’Hôpital together with the fundamental theorem of calculus gives exactly the quotient in (a).'),A(r'Therefore the limit is $\boxed4$.')])])
a116=lambda z:-9*math.atan(math.cos(z))*math.sin(z)/(1+math.cos(z)**2); rr116=roots(lambda z:a116(z)-1,0,math.pi)
checked(116,'All acceleration/displacement roots bracketed on [0,pi].',len(rr116)==2 and all(abs(a116(z)-1)<1e-8 for z in rr116))
add(116,'Acceleration as a function of displacement','Kinematics: differentiation',r'A particle has velocity $v(s)=3\arctan(\cos s)$ metres per second for $0\le s\le\pi$, where $s$ is displacement in metres.',[P('a','Find acceleration in terms of $s$.',[M(r'$a=dv/dt=(dv/ds)(ds/dt)=v\,dv/ds$.'),M('Differentiate the inverse tangent by the chain rule.'),A(r'$dv/ds=-3\sin s/(1+\cos^2s)$.'),A(r'$\boxed{a(s)=-\frac{9\arctan(\cos s)\sin s}{1+\cos^2s}}$.')]),P('b',r'Use a graph to find all displacements where $a=1\text{ m s}^{-2}$.',[M(r'Intersect $y=a(s)$ with $y=1$ on $[0,\pi]$.'),A('$\\boxed{s='+',\ '.join(f'{z:#.3g}' for z in rr116)+'\\text{ m}}$.')])],calc=True,solutionDiagram=graph([(a116,'#7a1f24'),(lambda z:1,'#777777')],(0,math.pi),(-3.5,3.5),[(z,1,f's={z:#.3g}') for z in rr116],xlabel='s',ylabel='a'))
add(117,'The domain of an implicit curve','Implicit differentiation',r'The curve $C$ satisfies $2x^2-xy+y^2+ax=4$, with $a>0$. Its domain is $p\le x\le q$, where $q-p=32/7$.',[P('a',r'Show $dy/dx=(y-4x-a)/(2y-x)$.',[M(r'$4x-y-xy\prime+2yy\prime+a=0$.'),M('Collect the derivative terms.'),A(r'$\boxed{y\prime=(y-4x-a)/(2y-x)}$.')]),P('b','Find $a$.',[M(r'Regard the equation as $y^2-xy+(2x^2+ax-4)=0$.'),A(r'Real $y$ requires discriminant $-7x^2-4ax+16\ge0$.'),M('The domain endpoints are roots of $7x^2+4ax-16=0$.'),A(r'$q-p=\sqrt{16a^2+448}/7$.'),M(r'$\sqrt{16a^2+448}=32\Rightarrow a^2=36$.'),A(r'Since $a>0$, $\boxed{a=6}$; the domain is $[-4,4/7]$.')])])
checked(118,'Specified normal point and two horizontal-tangent points satisfy the curve.',all(X*X+Y*Y-4*X*Y+108==0 for X,Y in [(12,42),(12,6),(-12,-6)]))
add(118,'Tangents on an implicit hyperbola','Implicit differentiation',r'A curve is defined by $x^2+y^2-4xy+108=0$.',[P('a',r'Show $dy/dx=(4y-2x)/(2y-4x)$.',[M(r'$2x+2yy\prime-4(y+xy\prime)=0$.'),M('Collect the $y\prime$ terms.'),A(r'$\boxed{y\prime=(4y-2x)/(2y-4x)}$.')]),P('b','Find the normal at $(12,42)$.',[M('Substitute in the derivative.'),A(r'The tangent gradient is $144/36=4$.'),M('The normal gradient is $-1/4$.'),A(r'$\boxed{y-42=-\frac14(x-12)}$.')]),P('c','Find the distance between the two points where the tangent is perpendicular to the $y$-axis.',[M('Such a tangent is horizontal, so $4y-2x=0$.'),A(r'$x=2y$.'),M('Substitute into the implicit equation.'),A(r'$4y^2+y^2-8y^2+108=0$.'),A(r'$y=\pm6$ and $x=\pm12$ with matching signs.'),R(r'At these points the derivative denominator is nonzero, so both are valid horizontal tangents.'),M('Use the distance formula between $(12,6)$ and $(-12,-6)$.'),A(r'$\boxed{\sqrt{24^2+12^2}=12\sqrt5}$.')])])
line119=lambda z:8*z/23-4; fun119=lambda z:line119(z)**2+6*z*line119(z)+math.exp(z)-17
rr119=roots(fun119,-20,15);second119=[z for z in rr119 if abs(z)>1e-6][0]
checked(119,'Second normal intersection bracketed and substituted; strict convexity guarantees only two roots.',len(rr119)==2 and abs(fun119(second119))<1e-7)
add(119,'A normal meeting an exponential curve again','Implicit differentiation',r'The curve is $y^2+6xy+e^x=17$. The point $P=(0,b)$ lies on it with $b<0$.',[P('a','Find $b$.',[M(r'$b^2+1=17$.'),A(r'$\boxed{b=-4}$.')]),P('b',r'Show $dy/dx=-(6y+e^x)/(2y+6x)$.',[M(r'$2yy\prime+6(y+xy\prime)+e^x=0$.'),A(r'$(2y+6x)y\prime=-6y-e^x$.'),M('Divide by $2y+6x$ where nonzero.'),A(r'$y\prime=-(6y+e^x)/(2y+6x)$.')]),P('c','Find the normal at $P$.',[A(r'The tangent gradient is $-23/8$.'),M(r'The normal gradient is $8/23$.'),A(r'$\boxed{y=\frac8{23}x-4}$.')]),P('d','Find its second intersection with the curve, to three significant figures.',[M('Substitute the normal equation into the curve.'),A(r'$(8x/23-4)^2+6x(8x/23-4)+e^x=17$.'),M('Solve numerically, excluding $x=0$.'),A(f'$\\boxed{{({second119:#.3g},\ {line119(second119):#.3g})}}$.')]),P('e',r'For $u=y^4$ on the negative-$y$ branch, find $du/dx$ at $x=0$.',[M(r'$du/dx=4y^3\,dy/dx$.'),M(r'Substitute $y=-4$ and $dy/dx=-23/8$.'),A(r'$\boxed{du/dx=736}$.')])],calc=True)
