add(120,'A divided circular-segment water tank','Related rates',r'A 4 m long tank has circular cross-section of radius $1.5$ m, truncated by a horizontal top. A vertical partition through the centre $O$ divides it into equal left and right compartments. In each compartment, water occupies a half-segment: the radius to the water edge makes angle $\gamma$ with the downward vertical, with $0\le\gamma\le3\pi/4$. Its cross-sectional area is $\frac12(1.5)^2(\gamma-\sin\gamma\cos\gamma)$. The right and left angles are $\alpha$ and $\beta$.',[P('a',r'Find the litres of water in the right compartment when $\alpha=\pi/3$, to the nearest litre.',[M('Multiply the given cross-sectional area by length 4.'),A(r'$V=4.5(\pi/3-\sqrt3/4)\text{ m}^3$.'),A(f'$\\boxed{{{round(litres120)}\\text{{ litres}}}}$.')]),P('b',r'Find the volume $V$ in the left compartment in terms of $\beta$.',[M(r'Use the half-segment area with angle $\beta$.'),M('Multiply by the tank length 4 m.'),A(r'$\boxed{V=4.5(\beta-\sin\beta\cos\beta)\text{ m}^3}$.')]),P('c',r'Water enters the left compartment at $0.002\text{ m}^3\text{ s}^{-1}$. Find $d\beta/dt$ at $\beta=2\pi/3$, to three significant figures.',[M(r'$dV/d\beta=4.5(1-\cos2\beta)=9\sin^2\beta$.'),M(r'$dV/dt=(dV/d\beta)(d\beta/dt)$.'),A(r'At $\beta=2\pi/3$, $dV/d\beta=27/4$.'),A(r'$\boxed{d\beta/dt=0.000296\text{ rad s}^{-1}}$.')]),P('d',r'Starting at $\beta=2\pi/3$, find the time until the left compartment is full, to the nearest minute.',[M(r'Full volume is $V(3\pi/4)$.'),M(r'Additional volume is $V(3\pi/4)-V(2\pi/3)$.'),A(r'Time in minutes is $[V(3\pi/4)-V(2\pi/3)]/(0.002\cdot60)$.'),A(f'$\\boxed{{{round(duration120)}\\text{{ minutes}}}}$.')])],calc=True,diagram=svg120)
f121=(x**3+2*x-16)/(4*x); checked(121,'Stationary and inflexion coordinates satisfy exact derivatives and function values.',s.diff(f121,x).subs(x,-2)==0 and f121.subs(x,-2)==s.Rational(7,2) and s.simplify(s.diff(f121,x,2).subs(x,2**s.Rational(4,3)))==0 and s.simplify(f121.subs(x,2**s.Rational(4,3)))==s.Rational(1,2))
add(121,'An algebraic curve with an inflexion','Stationary points and concavity',r'Let $f(x)=\dfrac{x^3+2x-16}{4x}$ for $x\ne0$.',[P('a','Find the local minimum $A$.',[M(r'$f=x^2/4+1/2-4/x$.'),A(r'$f\prime=x/2+4/x^2$.'),M(r'$f\prime=0\Rightarrow x^3=-8$.'),A(r'$A=(-2,7/2)$.'),R(r'$f\prime\prime=1/2-8/x^3$ is $3/2>0$ at $x=-2$, confirming a minimum.')]),P('b',r'Show there is exactly one inflexion point $B$. Write $B=(2^p,2^q)$ and find $p,q$.',[M(r'$f\prime\prime=1/2-8/x^3$.'),M(r'$f\prime\prime=0\Rightarrow x^3=16$.'),A(r'The only real candidate is $x=2^{4/3}$.'),R(r'For positive $x$, $f\prime\prime$ changes from negative to positive there.'),R(r'For negative $x$, $f\prime\prime>0$ throughout; $x=0$ is outside the domain.'),M(r'Substitute $x=2^{4/3}$ into $x^2/4+1/2-4/x$.'),A(r'The power terms cancel, giving $y=1/2=2^{-1}$.'),A(r'$\boxed{p=4/3,\ q=-1}$.')]),P('c','Sketch the graph, labelling $A$, $B$ and the vertical asymptote.',[A(r'Vertical asymptote $x=0$, with $f\to+\infty$ from the left and $f\to-\infty$ from the right.'),A(r'Left branch has the correctly placed minimum $A=(-2,7/2)$.'),A(r'Right branch increases through inflexion $B=(2^{4/3},1/2)$.'),A(r'Both distant ends rise as $x^2/4+1/2$, and the right branch crosses the positive $x$-axis.')])],solutionDiagram=graph([(lambda z:(z**3+2*z-16)/(4*z),'#7a1f24')],(-6,6),(-10,16),[(-2,3.5,'A'),(2**(4/3),.5,'B')]))
add(122,'Cubic injectivity and inverse','Inverse functions and differentiation',r'Let $g(x)=ax^3+bx^2+cx+d$, with $a\ne0$ and real coefficients.',[P('a',r'Find $g\prime(x)$ and show that if $g$ is not one-to-one on $\mathbb R$, then $b^2-3ac>0$.',[A(r'$g\prime=3ax^2+2bx+c$.'),R('If this quadratic has no two distinct roots, it keeps one sign (apart from at most one zero), so the cubic is strictly monotone and one-to-one.'),R(r'Therefore non-injectivity requires $(2b)^2-4(3a)c>0$, hence $b^2-3ac>0$.')]),P('b',r'Now let $f(x)=x^3/4+3x^2/4+3x/4+9/4$. Show its inverse exists, write $f=p(x+1)^3+q$, and find $f^{-1}$.',[A(r'$f\prime=\frac34(x+1)^2\ge0$.'),R('It vanishes only at one point, so $f$ is strictly increasing on the real line and has an inverse.'),M('Complete the cube.'),A(r'$f=\frac14(x+1)^3+2$.'),A(r'Interchange the input and output variables to define the inverse on $\mathbb R$.'),M(r'Solve $y=\frac14(x+1)^3+2$ for $x$.'),A(r'$\boxed{f^{-1}(x)=\sqrt[3]{4x-8}-1}$.')]),P('c','Give three ordered transformations from $y=x^3$ to $y=f(x)$.',[A('Translate 1 unit to the left.'),A('Scale vertically by factor $1/4$.'),A('Translate 2 units upward. Equivalent correctly ordered sequences are accepted.')]),P('d','Sketch $f$ and its inverse together, labelling their axis intercepts.',[A(r'$f$ has intercepts $(-3,0)$ and $(0,9/4)$.'),A(r'$f^{-1}$ has intercepts $(9/4,0)$ and $(0,-3)$.'),A('Both are increasing cubic/cube-root shaped curves.'),A('They are reflections of each other in $y=x$.')])])
f123=8*s.sin(x)**2+s.Rational(19,2)*s.sin(2*x)+s.tan(x)-16
fp123=s.diff(f123,x);fpp123=s.diff(fp123,x);f123num=s.lambdify(x,f123,'numpy');fp123num=s.lambdify(x,fp123,'numpy');fpp123num=s.lambdify(x,fpp123,'numpy')
ri123=roots(fpp123num,0,math.pi/2-.00001)
checked(123,'Substitution polynomial factors (u−2)²(u−4); inflexion roots bracketed and checked.',s.expand((s.Symbol('u')-2)**2*(s.Symbol('u')-4))==s.Symbol('u')**3-8*s.Symbol('u')**2+20*s.Symbol('u')-16 and len(ri123)==2 and all(abs(fpp123num(z))<1e-6 and fpp123num(z-1e-5)*fpp123num(z+1e-5)<0 for z in ri123))
add(123,'Trigonometric roots via a cubic','Trigonometric differentiation',r'Let $f(x)=8\sin^2x+\frac{19}{2}\sin2x+\tan x-16$ for $0\le x<\pi/2$.',[P('a',r'Find $f\prime$, sketch it, and find the $x$-coordinates of all inflexion points of $f$.',[A(r'$f\prime=8\sin2x+19\cos2x+\sec^2x$.'),M(r'$f\prime\prime=16\cos2x-38\sin2x+2\sec^2x\tan x$.'),M(r'Solve $f\prime\prime=0$ and check its sign changes on the domain.'),A('$\\boxed{x='+',\ '.join(f'{z:#.3g}' for z in ri123)+'}$; both are inflexion points.'),A(r'Sketch $f\prime$ from $(0,20)$, showing its turning points at these values and tending to $+\infty$ as $x\to\pi/2^-$.')]),P('b',r'Put $u=\tan x$. Express $\sin x$ and $\sin2x$ in terms of $u$, then show that $f(x)=0$ is equivalent to $u^3-8u^2+20u-16=0$.',[M(r'$1+\tan^2x=\sec^2x$, and sine/cosine are nonnegative here.'),A(r'$\sin x=u/\sqrt{1+u^2}$.'),M(r'$\sin2x=2\sin x\cos x$.'),A(r'$\sin2x=2u/(1+u^2)$.'),M('Substitute into the equation.'),A(r'$8u^2/(1+u^2)+19u/(1+u^2)+u-16=0$.'),M(r'Multiply by $1+u^2>0$.'),A(r'$8u^2+19u+u+u^3-16-16u^2=0$.'),A(r'$u^3-8u^2+20u-16=0$.')]),P('c','Solve $f(x)=0$ exactly.',[M(r'Factor the cubic as $(u-2)^2(u-4)=0$.'),A(r'$u=2$ or $4$; both are allowed by $u\ge0$.'),A(r'$\boxed{x=\arctan2,\ \arctan4}$.')])],calc=True,solutionDiagram=graph([(fp123num,'#7a1f24')],(0,1.5),(-10,55),[(z,float(fp123num(z)),f'x={z:#.3g}') for z in ri123],ylabel="f′(x)"))
add(124,'Induction for higher derivatives','Higher derivatives and induction',r'Let $f(x)=(x+2)e^{-3x}$ for $x\in\mathbb R$.',[P('a',r'Find $f\prime(x)$.',[M('Use the product rule.'),A(r'$\boxed{f\prime=(-3x-5)e^{-3x}}$.')]),P('b',r'Prove by induction that $f^{(n)}(x)=[n(-3)^{n-1}+(-3)^n(x+2)]e^{-3x}$ for every positive integer $n$.',[M('Check the base case $n=1$.'),A(r'The formula gives $[1-3(x+2)]e^{-3x}=(-3x-5)e^{-3x}$.'),M('Assume the formula is true for $n=k$.'),M('Differentiate the assumed expression using the product rule.'),A(r'$f^{(k+1)}=[(-3)^k-3k(-3)^{k-1}-3(-3)^k(x+2)]e^{-3x}$.'),A(r'$=[(k+1)(-3)^k+(-3)^{k+1}(x+2)]e^{-3x}$.'),R('This is the formula for $k+1$; the base and inductive step establish it for all positive integers.')]),P('c','Find and classify all local extrema.',[M(r'$(-3x-5)e^{-3x}=0$.'),A(r'$x=-5/3$.'),A(r'$f(-5/3)=e^5/3$.'),M(r'$f\prime$ is positive before $-5/3$ and negative after it.'),R(r'Thus $\boxed{(-5/3,e^5/3)}$ is the only local maximum; there is no local minimum.')]),P('d','Find and justify all inflexion points.',[M(r'$f\prime\prime=(9x+12)e^{-3x}$.'),A(r'$f\prime\prime=0\Rightarrow x=-4/3$.'),A(r'$f(-4/3)=2e^4/3$.'),R(r'$9x+12$ changes sign, while the exponential is positive.'),A(r'The unique inflexion is $\boxed{(-4/3,2e^4/3)}$.')]),P('e','Sketch $f$, showing these points and all intercepts.',[A(r'Intercepts $(-2,0)$ and $(0,2)$.'),A('Correct maximum and inflexion in the correct order.'),A(r'$f\to-\infty$ as $x\to-\infty$ and $f\to0^+$ as $x\to+\infty$.')])])
add(125,'Inverse cosine, symmetry and inversion','Inverse functions and differentiation',r'Let $f(x)=\arccos\left(\dfrac{x^2-4}{x^2+4}\right)$ for $x\in\mathbb R$.',[P('a','Show $f$ is even.',[R(r'Replacing $x$ by $-x$ leaves both $x^2$ terms unchanged, so $f(-x)=f(x)$.')]),P('b','Find the horizontal asymptote.',[M(r'As $x\to\pm\infty$, $(x^2-4)/(x^2+4)\to1$.'),A(r'$f(x)\to\arccos1=0$, so $\boxed{y=0}$.')]),P('c',r'Find $f\prime$ for $x\ne0$ and show that $f$ is increasing for $x<0$.',[M(r'For $u=(x^2-4)/(x^2+4)$, $f\prime=-u\prime/\sqrt{1-u^2}$.'),M('Use the quotient rule for $u$.'),A(r'$u\prime=16x/(x^2+4)^2$.'),M(r'$1-u^2=[(x^2+4)^2-(x^2-4)^2]/(x^2+4)^2$.'),A(r'$1-u^2=16x^2/(x^2+4)^2$.'),A(r'$\sqrt{1-u^2}=4|x|/(x^2+4)$.'),A(r'$\boxed{f\prime=-4x/[|x|(x^2+4)]}$ for $x\ne0$.'),M(r'For $x<0$, $|x|=-x$.'),R(r'$f\prime=4/(x^2+4)>0$, so $f$ is increasing there.')]),P('d',r'Let $g$ be the restriction of $f$ to $x\ge0$. Find its range.',[M(r'$g(0)=\pi$ and $g$ decreases toward 0 without reaching it.'),A(r'$\boxed{(0,\pi]}$.')]),P('e',r'Find $g^{-1}(x)$.',[M(r'$\cos y=(x^2-4)/(x^2+4)$.'),A(r'$x^2=4(1+\cos y)/(1-\cos y)$.'),M('Take the nonnegative square root because $g$ has domain $x\ge0$.'),A(r'$\boxed{g^{-1}(x)=2\sqrt{\frac{1+\cos x}{1-\cos x}}=2\cot(x/2)}$.')]),P('f',r'State the domain of $g^{-1}$.',[A(r'$\boxed{(0,\pi]}$.')]),P('g',r'Sketch $g^{-1}$, labelling asymptotes and intercepts.',[A(r'Vertical asymptote $x=0$.'),A(r'The $x$-intercept and included endpoint is $(\pi,0)$; there is no $y$-intercept.'),A('The curve decreases from $+\infty$ to 0 and is concave up on its domain.')])])
