# Normalize derivative typography everywhere before writing the final checkpoint.
def normalize(obj):
 if isinstance(obj,str):
  return re.sub(r'([A-Za-z)])((?:\\prime)+)', lambda m:m.group(1)+"'"*m.group(2).count('\\prime'),obj)
 if isinstance(obj,list):return [normalize(v) for v in obj]
 if isinstance(obj,dict):return {k:normalize(v) for k,v in obj.items()}
 return obj
